function drawFlowers() {
  for(let i=0;i<42;i++){
    const x=(i*173+31)%1000, y=410+(i*83%190), h=9+(i*19%18);
    if(y>bird.y-27&&y<bird.y+23&&Math.abs(x-bird.x)<82) continue;
    path([[x,y+8],[x+Math.sin(i)*2,y-h]],'#849778',1.5,.55);
    if(i%3===0) path([[x,y-2],[x-5,y-7]],'#91a17d',1.2,.6);
    wash(x,y-h,5,4,flowerColors[i%flowerColors.length],.75);
    for(let j=0;j<4;j++){const a=j*Math.PI/2;wash(x+Math.cos(a)*3.3,y-h+Math.sin(a)*2.8,2.5,2.2,flowerColors[i%flowerColors.length],.8);}
    wash(x,y-h,1.5,1.5,'#c69b58',.85);
  }
  for(let i=0;i<19;i++){const x=(i*241+80)%1000,y=393+(i*61%197);path([[x,y+10],[x-3,y-9]],'#778d70',2,.4);path([[x-2,y+2],[x+6,y-5]],'#829678',3,.37);}
}
function seedPoints(){
  const spots=[[145,470],[282,515],[395,426],[594,489],[750,435],[864,519],[690,555],[112,554]];
  return spots.map(([x,y],i)=>({x,y,got:false,phase:i*1.7}));
}
function paintSeed(s){
  if(s.got)return;
  const bob=Math.sin(elapsed*2.2+s.phase)*3, x=s.x,y=s.y+bob;
  wash(x,y+5,18,10,'#bba46b',.18);
  ctx.save();ctx.translate(x,y);ctx.rotate(-.38);
  wash(-2,0,6,9,'#dab65f',.94);wash(-3,-2,3.8,6,'#f3d982',.9);
  path([[-1,-6],[5,-11]],'#8da077',2,.75);
  ctx.restore();
  ctx.save();ctx.globalAlpha=.6+.35*Math.sin(elapsed*3+s.phase);ctx.fillStyle='#fff7d1';ctx.beginPath();ctx.arc(x+8,y-7,1.7,0,Math.PI*2);ctx.fill();ctx.restore();
}
function paintBird(){
  const bob=state==='playing'?Math.abs(Math.sin(bird.step))*2.2:Math.sin(elapsed*1.5)*1.5;
  const x=bird.x,y=bird.y+bob;
  // Grounding shadow, then an airy ochre wash under the bird.
  wash(x-3,y+1,63,18,'#8e8067',.18);wash(x-14,y-2,94,22,'#d7c79f',.21);
  ctx.save();ctx.translate(x,y);ctx.scale(bird.dir,1);
  // Tiny stepping legs and toes.
  const stride=state==='playing'?Math.sin(bird.step*2)*4:0;
  path([[-8,-5],[-10+stride,-1],[-17+stride,0]],'#8c7555',2,.85);
  path([[12,-5],[13-stride,-1],[20-stride,0]],'#8c7555',2,.85);
  path([[-19+stride,0],[-13+stride,-1]],'#8c7555',1.5,.8);path([[18-stride,0],[24-stride,-1]],'#8c7555',1.5,.8);
  // Rounded fanned tail peeking from the left.
  wash(-48,-34,29,25,'#b79472',.78,-.2);wash(-54,-33,22,18,'#ccb18c',.67,.22);
  // Plump warm body, with translucent overlapping feather washes.
  wash(-10,-31,55,39,'#b99479',.96,-.08);wash(-16,-25,48,31,'#cfb397',.82,-.18);
  wash(-30,-18,33,22,'#a98775',.61,.12);wash(11,-21,32,28,'#d6b89a',.65,-.22);
  for(let i=0;i<17;i++){
    const fx=-48+(i*29%75), fy=-46+(i*17%34);
    ctx.save();ctx.translate(fx,fy);ctx.rotate(-.3+(i%4)*.17);ctx.globalAlpha=.22+(i%3)*.07;
    ctx.fillStyle=i%2?'#8f7664':'#ead1ad';ctx.beginPath();ctx.ellipse(0,0,5+(i%4),2.7,0,0,Math.PI*2);ctx.fill();ctx.restore();
  }
  // Long teal breast and graceful upright neck.
  ctx.beginPath();ctx.moveTo(-2,-51);ctx.bezierCurveTo(-17,-70,-8,-100,4,-117);ctx.bezierCurveTo(13,-128,31,-121,29,-107);ctx.bezierCurveTo(25,-90,26,-76,39,-59);ctx.bezierCurveTo(46,-48,32,-35,16,-38);ctx.closePath();
  const neck=ctx.createLinearGradient(-9,-115,35,-52);neck.addColorStop(0,'#527c7e');neck.addColorStop(.52,'#39747a');neck.addColorStop(1,'#789b8c');ctx.fillStyle=neck;ctx.globalAlpha=.96;ctx.fill();
  wash(11,-83,9,34,'#5b9290',.38,-.16);wash(28,-54,16,15,'#527d78',.39);
  // Flecks of breast plumage.
  for(let i=0;i<8;i++){const px=5+(i%3)*8,py=-69-Math.floor(i/3)*8;wash(px,py,2.4,1.5,'#e1d9b8',.52,.3);}
  // Rose-crowned head and pale cheek.
  wash(20,-119,19,17,'#bd8b88',.96,-.2);wash(13,-124,12,10,'#d4a19a',.82,.3);
  wash(25,-113,11,9,'#e5d5bd',.94,-.2);
  // Beak, eye, and a quiet painted eye-line.
  ctx.fillStyle='#756f62';ctx.beginPath();ctx.moveTo(34,-120);ctx.quadraticCurveTo(49,-124,54,-117);ctx.quadraticCurveTo(44,-115,34,-116);ctx.closePath();ctx.fill();
  ctx.fillStyle='#fbf5df';ctx.beginPath();ctx.arc(25,-121,5.6,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#302f2a';ctx.beginPath();ctx.arc(26,-121,3.6,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#fffdf1';ctx.beginPath();ctx.arc(27,-122,1,0,Math.PI*2);ctx.fill();
  path([[33,-109],[38,-106]],'#a76f6d',1.7,.58);
  ctx.restore();
  // soft ring when a seed has just been found
  if(puff.length){ctx.save();puff.forEach(p=>{ctx.globalAlpha=Math.max(0,1-p.age/.7);ctx.strokeStyle='#e2c36e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,8+p.age*25,0,Math.PI*2);ctx.stroke();});ctx.restore();}
}

