    if(state==='playing'){
      time=Math.max(0,time-dt);
      let dx=(keys.has('right')?1:0)-(keys.has('left')?1:0);
      let dy=(keys.has('down')?1:0)-(keys.has('up')?1:0);
      if(dx||dy){const mag=Math.hypot(dx,dy);dx/=mag;dy/=mag;bird.x=clamp(bird.x+dx*155*dt,35,965);bird.y=clamp(bird.y+dy*145*dt,270,575);bird.step+=dt*10;if(dx)bird.dir=dx>0?1:-1;}
      seeds.forEach(s=>{if(!s.got&&Math.hypot(s.x-bird.x,s.y-bird.y)<39){s.got=true;found++;seedLabel.textContent=found;puff.push({x:s.x,y:s.y,age:0});}});
      puff.forEach(p=>p.age+=dt);puff=puff.filter(p=>p.age<.7);
      timeLabel.textContent=`${Math.floor(time/60)}:${String(Math.ceil(time%60)).padStart(2,'0')}`;
      if(found===8)finish(true);else if(time<=0)finish(false);
    }
  }
  function paint(){
    paintBackground();seeds.forEach(paintSeed);paintBird();
    // Loose wisps of grass close to the viewer add depth without hiding the path.
    for(let i=0;i<13;i++){const x=(i*89+17)%1000,y=570+(i*31%29);path([[x,y],[x-3,y-9],[x-8,y-13]],'#879271',1.8,.34);}
  }
  function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);paint();requestAnimationFrame(frame);}
  function finish(won){
    state=won?'won':'lost';keys.clear();overlay.classList.remove('hidden');
    document.getElementById('dialog-kicker').textContent=won?'A lovely little harvest':'The light is growing soft';
    document.getElementById('dialog-title').textContent=won?'Well gathered, little one':'One more gentle stroll?';
    document.getElementById('dialog-copy').textContent=won?'Eight golden seeds, gathered with care. The meadow is grateful for your visit.':`You found ${found} of the eight golden seeds. There is always another sunny afternoon.`;
    document.getElementById('dialog-tip').textContent=won?'A perfect handful for a quiet day':'Take a breath, then wander again';
    startButton.innerHTML='Wander again&nbsp; →';
  }
  function begin(){
    found=0;time=75;bird.x=495;bird.y=440;bird.dir=1;bird.step=0;seeds=seedPoints();puff=[];state='playing';
    seedLabel.textContent='0';timeLabel.textContent='1:15';keys.clear();overlay.classList.add('hidden');canvas.focus({preventScroll:true});
  }
  startButton.addEventListener('click',begin);
  const keyMap={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};
  window.addEventListener('keydown',e=>{
    const dir=keyMap[e.key];if(dir){e.preventDefault();keys.add(dir);}
    if((e.key==='Enter'||e.key===' ')&&state!=='playing'){e.preventDefault();begin();}
  });
  window.addEventListener('keyup',e=>{const dir=keyMap[e.key];if(dir)keys.delete(dir);});
  window.addEventListener('blur',()=>keys.clear());
  document.querySelectorAll('.pad-button').forEach(button=>{
    const dir=button.dataset.dir;
    button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);keys.add(dir);});
    const release=e=>{e.preventDefault();keys.delete(dir);};
    button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',()=>keys.delete(dir));
  });
  seeds=seedPoints();requestAnimationFrame(frame);
})();
</script>
</body>
</html>

